{
  "title": "Dispute Analysis Techniques",
  "categories": [
    {
      "name": "Perspective & Position Analysis",
      "techniques": [
        {
          "name": "Adversarial Steelmanning",
          "aliases": ["Red Team Perspective"],
          "summary": "Construct the strongest possible version of the opposing party's argument from their internal viewpoint. Not to validate, but to anticipate, identify superficially meritorious points, and prepare targeted rebuttals.",
          "use_case": "Understanding opponent"
        },
        {
          "name": "Devil's Advocate Analysis",
          "aliases": [],
          "summary": "Systematically argue against your own position to stress-test it. Differs from steelmanningâ€”here you're attacking yourself, not inhabiting their perspective.",
          "use_case": "Testing your own case"
        },
        {
          "name": "Interests vs Positions Analysis",
          "aliases": [],
          "summary": "Separate what they're demanding (positions) from why they want it (interests). Often reveals negotiation space invisible when focused only on stated demands.",
          "source": "Fisher & Ury, Getting to Yes",
          "use_case": "Negotiation preparation"
        },
        {
          "name": "Stakeholder Mapping",
          "aliases": [],
          "summary": "Identify all parties with influence or interest in the outcome. Map their motivations, power, and relationships. Useful when the person you're negotiating with isn't the real decision-maker.",
          "use_case": "Understanding opponent"
        }
      ]
    },
    {
      "name": "Evidence & Documentation Techniques",
      "techniques": [
        {
          "name": "Critical Incident Technique",
          "aliases": [],
          "summary": "Focus analysis on specific, documented events rather than general patterns. Each incident examined for: what happened, when, who was involved, what evidence exists. Stronger for legal purposes than narrative generalizations.",
          "use_case": "Preparing legal claim"
        },
        {
          "name": "Timeline/Chronology Analysis",
          "aliases": [],
          "summary": "Map all events sequentially with precise dates. Reveals gaps, impossibilities, and contradictions invisible in narrative form. Essential for exposing after-the-fact justifications.",
          "use_case": "Preparing legal claim"
        },
        {
          "name": "Documentary Gap Analysis",
          "aliases": [],
          "summary": "Identify what documentation should exist but doesn't. Absence of expected records (meeting notes, emails, approvals) can be as significant as what exists.",
          "use_case": "Preparing legal claim"
        },
        {
          "name": "Contradiction Mapping",
          "aliases": [],
          "summary": "Systematically document where the opposing party's statements contradict each other, their own documents, or established facts. Organize by theme for maximum impact.",
          "use_case": "Preparing legal claim"
        },
        {
          "name": "Ghost Clause Identification",
          "aliases": [],
          "summary": "Identify unwritten practices that operated throughout a relationship despite formal contract terms. Useful for demonstrating selective enforcement or establishing course of dealing.",
          "use_case": "Exposing bad faith"
        }
      ]
    },
    {
      "name": "Strategic Assessment",
      "techniques": [
        {
          "name": "BATNA Analysis",
          "aliases": ["Best Alternative to Negotiated Agreement"],
          "summary": "Identify your best outcome if negotiation fails. Defines your walk-away point and negotiation leverage.",
          "use_case": "Negotiation preparation"
        },
        {
          "name": "WATNA Analysis",
          "aliases": ["Worst Alternative to Negotiated Agreement"],
          "summary": "Identify your worst case if negotiation fails. Defines risk exposure and informs acceptable settlement range.",
          "use_case": "Negotiation preparation"
        },
        {
          "name": "ZOPA Identification",
          "aliases": ["Zone of Possible Agreement"],
          "summary": "Identify the overlap between what each party would accept. If no overlap exists, negotiation is futileâ€”pursue alternatives.",
          "use_case": "Negotiation preparation"
        },
        {
          "name": "Leverage Mapping",
          "aliases": [],
          "summary": "Identify all sources of power each party holds: information, relationships, time pressure, financial capacity, reputation risk, legal exposure. Assess how leverage shifts over time.",
          "use_case": "Negotiation preparation"
        },
        {
          "name": "Cost-Benefit Decision Tree",
          "aliases": [],
          "summary": "Map each potential action, its likely outcomes, probability of each outcome, and associated costs/benefits. Quantifies whether pursuing a claim is economically rational.",
          "use_case": "Testing your own case"
        },
        {
          "name": "Pre-Mortem Analysis",
          "aliases": [],
          "summary": "Assume your strategy has failed. Work backward to identify what went wrong. Surfaces risks and weaknesses before they materialize.",
          "use_case": "Testing your own case"
        }
      ]
    },
    {
      "name": "Root Cause & Pattern Analysis",
      "techniques": [
        {
          "name": "5 Whys",
          "aliases": [],
          "summary": "Repeatedly ask 'why' (typically five times) to drill from surface symptoms to root causes. Useful for understanding what actually drove the breakdown versus stated reasons.",
          "use_case": "Understanding opponent"
        },
        {
          "name": "Selective Enforcement Analysis",
          "aliases": [],
          "summary": "Document instances where a party enforced certain terms while ignoring others. Demonstrates inconsistency and undermines claims that they're simply following the contract.",
          "use_case": "Exposing bad faith"
        },
        {
          "name": "Pattern of Conduct Analysis",
          "aliases": [],
          "summary": "Identify repeated behaviors across multiple incidents that reveal true operating practice versus stated policy. Establishes course of dealing for legal purposes.",
          "use_case": "Exposing bad faith"
        }
      ]
    },
    {
      "name": "Narrative & Communication",
      "techniques": [
        {
          "name": "Narrative/Counter-Narrative Analysis",
          "aliases": [],
          "summary": "Identify the story each party is telling. Break down: protagonist, antagonist, inciting incident, justification, desired resolution. Craft counter-narrative that reframes the same facts.",
          "use_case": "Crafting communications"
        },
        {
          "name": "Framing Analysis",
          "aliases": [],
          "summary": "Examine how language choices shape perception. Identify their frames; construct yours. Example: 'Communication breakdown' vs 'payment dispute'.",
          "use_case": "Crafting communications"
        },
        {
          "name": "Audience Analysis",
          "aliases": [],
          "summary": "Tailor arguments to decision-maker. What matters to a judge differs from a mediator differs from a commercial counterparty. Adjust emphasis accordingly.",
          "use_case": "Crafting communications"
        }
      ]
    },
    {
      "name": "Negotiation Dynamics",
      "techniques": [
        {
          "name": "Anchoring Analysis",
          "aliases": [],
          "summary": "Identify who set the initial reference points and how they're shaping the negotiation. First numbers, first characterizations tend to anchor subsequent discussion.",
          "use_case": "Negotiation preparation"
        },
        {
          "name": "Concession Pattern Analysis",
          "aliases": [],
          "summary": "Track what each party has conceded and when. Reveals priorities, pressure points, and negotiation style. Informs what to ask for next.",
          "use_case": "Negotiation preparation"
        },
        {
          "name": "Face-Saving Pathway Design",
          "aliases": [],
          "summary": "Identify routes that let the opposing party concede without appearing to lose. Often unlocks settlements that pure adversarial pressure cannot.",
          "use_case": "Negotiation preparation"
        }
      ]
    }
  ],
